package com.tracker.controller; import com.tracker.dto.AuthDtos.*; import com.tracker.service.AuthService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.Map; @RestController @RequestMapping("/api/auth") public class AuthController {private final AuthService service; public AuthController(AuthService s){service=s;} @PostMapping("/register") public AuthResponse register(@Valid @RequestBody Register r){return service.register(r);} @PostMapping("/login") public AuthResponse login(@Valid @RequestBody Login r){return service.login(r);} @PostMapping("/forgot-password") public Map<String,String> forgot(@Valid @RequestBody ForgotPassword r){return Map.of("message","If an account exists for this email, password reset instructions will be sent.");}}
